constant G(x)  = sin(x) * (2 - cos(x)) - x
constant G'(x) = 2 * cos(x) * (1 - cos(x))     // sign of G' = sign of cos x

function CRITICAL_SCALE():
    // G is strictly increasing on [0, pi/2] with G(0) = 0, hence G > 0 there;
    // G is strictly decreasing on [pi/2, pi] with G(pi/2) = 2 > 0 > -pi = G(pi).
    // Therefore [pi/2, pi] brackets the unique sign change.
    lo <- pi/2 ;  hi <- pi
    repeat until hi - lo < tol:
        mid <- (lo + hi) / 2
        if G(lo) * G(mid) < 0 then hi <- mid else lo <- mid
    return (lo + hi) / 2                        // x_c in [2.1, 2.2)

function CRITICAL_TIME_BANDWIDTH():
    return 2 * CRITICAL_SCALE()                 // c = 4.27836...

function CLASSIFY(T, Delta):
    require T > 0 and Delta > 0
    R_mid    <- 2T * (sinc(-Delta*T/2) + sinc(Delta*T/2))
    R_centre <- 2T * (sinc(0) + sinc(Delta*T))
    x <- Delta * T / 2
    resolved <- (R_mid < R_centre)              // equivalent to G(x) < 0
    return (resolved, margin = -G(x))

function MINIMUM_OBSERVATION_TIME(Delta):
    return 2 * CRITICAL_TIME_BANDWIDTH() / Delta

function INT_DIST(x):
    return |x - round(x)|                       // ||x||

function CONVERGENTS(alpha, bound):
    (p_prev, q_prev) <- (1, 0) ;  (p, q) <- (floor(alpha), 1) ;  x <- alpha
    while q <= bound do
        emit (p, q)
        frac <- x - floor(x)
        if frac = 0 then stop                   // alpha is rational; expansion terminates
        x <- 1 / frac ;  a <- floor(x)
        (p_prev, p) <- (p, a*p + p_prev)
        (q_prev, q) <- (q, a*q + q_prev)        // Fibonacci-fast growth => O(log bound) steps

function BEST_MULTIPLIER(alpha, N):
    best <- (1, INT_DIST(alpha))
    for (p, q) in CONVERGENTS(alpha, N) do
        if INT_DIST(q * alpha) < best.defect then best <- (q, INT_DIST(q * alpha))
    return best                                 // guarantees defect <= 1/(N+1)

function CERTIFY_RESONANCE(alpha, N):
    (q, defect) <- BEST_MULTIPLIER(alpha, N)
    M_max <- floor((N + 1) / 2)
    for M <- 1 to M_max do
        // defect <= 1/(N+1) <= 1/(2M), so the Jordan main-lobe bound applies
        assert |S_M(q * alpha)| >= (2/pi) * M
    return (q, defect, M_max)
